begin;
select plan(24);
select has_table('campaign','webinar_publisher_launches','immutable launch lineage table exists');
select has_table('campaign','webinar_publisher_operations','durable operation table exists');
select has_table('campaign','webinar_publisher_admissions','separate provenance admission exists');
select has_table('campaign','webinar_publisher_attempts','stage effect attempts are durable');
select has_table('integration','webinar_publisher_outbox','strict task outbox exists');
select ok(has_function_privilege('app_runtime','campaign.webinar_publisher_command(jsonb,text,jsonb)','EXECUTE'),'request runtime may call fixed command function');
select ok(has_function_privilege('app_runtime','campaign.webinar_publisher_worker(jsonb,text,jsonb)','EXECUTE'),'worker uses fixed function');
select ok(not has_function_privilege('app_runtime','campaign.webinar_publisher_admit(uuid,uuid,uuid,jsonb)','EXECUTE'),'ordinary runtime cannot invent provider admission');
select ok(has_function_privilege('publisher_admission_runtime','campaign.webinar_publisher_admit(uuid,uuid,uuid,jsonb)','EXECUTE'),'separate capability admits verified records');
select ok(not has_function_privilege('anon','campaign.webinar_publisher_command(jsonb,text,jsonb)','EXECUTE'),'anonymous has no launch command');
select ok(not has_function_privilege('authenticated','campaign.webinar_publisher_worker(jsonb,text,jsonb)','EXECUTE'),'browser role cannot checkpoint');
select ok(not has_function_privilege('support_runtime','campaign.webinar_publisher_command(jsonb,text,jsonb)','EXECUTE'),'support cannot launch');
select ok(not has_function_privilege('app_runtime','campaign.webinar_publisher_authorize(jsonb)','EXECUTE'),'authority helper is private');
select ok(not has_table_privilege('app_runtime','campaign.webinar_publisher_launches','INSERT'),'no direct runtime summary insertion');
select ok(not has_table_privilege('app_runtime','campaign.webinar_publisher_operations','UPDATE'),'no direct runtime lease or identity edit');
select ok(not has_table_privilege('app_runtime','campaign.webinar_publisher_admissions','INSERT'),'shape cannot confer provenance');
select ok(not has_table_privilege('app_runtime','campaign.webinar_publisher_attempts','DELETE'),'cannot erase possible remote write');
select ok(not has_table_privilege('app_runtime','integration.webinar_publisher_outbox','INSERT'),'command/outbox insert is atomic function only');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where relname in ('webinar_publisher_launches','webinar_publisher_operations','webinar_publisher_admissions','webinar_publisher_attempts','webinar_publisher_outbox')),'all new tables force RLS');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where proname in ('webinar_publisher_command','webinar_publisher_worker','webinar_publisher_admit','webinar_publisher_proof')),'capabilities use fixed empty search path');
select ok((select not rolcanlogin and not rolsuper and not rolbypassrls from pg_roles where rolname='publisher_admission_runtime'),'admission role has no login, superuser or RLS bypass');
select ok(not pg_has_role('app_runtime','publisher_admission_runtime','MEMBER'),'ordinary runtime cannot assume admission role');
select has_index('campaign','webinar_publisher_operations','webinar_publisher_one_active_idx','one active mutation lineage is enforced');
select has_index('campaign','webinar_publisher_attempts','webinar_publisher_attempts_pkey','one effect attempt per operation-stage is enforced');
select * from finish();
rollback;
